#include <string>

std::string markdownToHtml(const std::string& md_input) {
    cm_state* state = cmark_parse_options_new(CMARK_OPTION_SOURCEposition_INFO | CMARK Soft_BREAK);
    cm_document* document = cmarkparse(doc_md_input.c_str(), strlen(md_input.c_str()), state);

    // Get optimal renderer for HTML output (we'll use plain HTML)
