```javascript
function isPrime(n) {
    if (n <= 1) return false;
    for (let i = 2, sqrt = Math.sqrt(n); i <= sqrt; i++)
        if (n % i === 0) return false;
    return true;
}

function checkPrimes(arr) {
    for (const num of arr) {
        if (isPrime(num)) {
            console.log(`Found prime number: ${num}`);
            return; // exit loop as soon as we find a prime
        }
    }
}

// Example usage:
const arr = [4, 7, 22, 13, 30];
checkPrimes(arr);
```

In this code, the `isPrime` function checks if a given number is prime. The `checkPrimes` function iterates through the input array, applies `isPrime` to each number, and if it finds a prime, prints it to the console and exits the loop early using `return`. If no primes are found, it will simply complete without printing anything extra.

